def resolve(path, cwd, links):
    max_links = 8
    link_count = 0

    # Start with cwd if path doesn't start with '/'
    if not path.startswith('/'):
        current = cwd
    else:
        current = '/'

    # Split path into components and filter out empty strings
    if path.startswith('/'):
        components = [c for c in path.split('/') if c]
    else:
        components = [c for c in path.split('/') if c]

    i = 0
    while i < len(components):
        component = components[i]

        # Skip '.' and empty components
        if component == '.' or component == '':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if candidate is a symlink
        if candidate in links:
            # Follow the symlink
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Resolve remaining components from the link target
            if target.startswith('/'):
                # Absolute target - start from root
                current = '/'
                target_components = [c for c in target.split('/') if c]
            else:
                # Relative target - relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                target_components = [c for c in target.split('/') if c]

            # Insert target components and remaining components
            components = target_components + components[i+1:]
            i = 0
        else:
            # Not a symlink, move to this component
            current = candidate
            i += 1

    # Remove trailing slash except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

